//
//  JADE Cybersecurity Platform - iOS Security Engine
//  Mobile app security, device integrity, threat detection
//  Author: KOLLÁR SÁNDOR (CEO of JADE)
//

import Foundation
import UIKit
import Security
import CryptoKit
import Network
import LocalAuthentication

@objc class JADEiOSSecurity: NSObject {

    enum ThreatLevel: Int, CaseIterable {
        case safe = 0
        case low = 1
        case medium = 2
        case high = 3
        case critical = 4

        var description: String {
            switch self {
            case .safe: return "SAFE"
            case .low: return "LOW"
            case .medium: return "MEDIUM"
            case .high: return "HIGH"
            case .critical: return "CRITICAL"
            }
        }

        var emoji: String {
            switch self {
            case .safe: return "✅"
            case .low: return "🟨"
            case .medium: return "🟧"
            case .high: return "🔴"
            case .critical: return "💀"
            }
        }
    }

    struct SecurityEvent {
        let timestamp: Date
        let eventType: String
        let threatLevel: ThreatLevel
        let description: String
        let deviceInfo: [String: Any]
    }

    struct DeviceSecurityProfile {
        let isJailbroken: Bool
        let hasPasscode: Bool
        let isBiometricEnabled: Bool
        let osVersion: String
        let deviceModel: String
        let securityPatchLevel: String
        let encryptionStatus: Bool
    }

    private var securityEvents: [SecurityEvent] = []
    private let securityQueue = DispatchQueue(label: "jade.security.queue", qos: .userInitiated)
    private var isMonitoring = false

    // MARK: - Jailbreak Detection

    func detectJailbreak() -> ThreatLevel {
        let jailbreakIndicators = [
            "/Applications/Cydia.app",
            "/Library/MobileSubstrate/MobileSubstrate.dylib",
            "/bin/bash",
            "/usr/sbin/sshd",
            "/etc/apt",
            "/private/var/lib/apt/",
            "/private/var/lib/cydia",
            "/private/var/stash",
            "/System/Library/LaunchDaemons/com.ikey.bbot.plist",
            "/System/Library/LaunchDaemons/com.saurik.Cydia.Startup.plist"
        ]

        var detectedCount = 0

        for path in jailbreakIndicators {
            if FileManager.default.fileExists(atPath: path) {
                detectedCount += 1
            }
        }

        // Check if app can write to system directories
        let testPath = "/private/test_jailbreak.txt"
        if ((try? "test".write(toFile: testPath, atomically: true, encoding: .utf8)) != nil) {
            try? FileManager.default.removeItem(atPath: testPath)
            detectedCount += 2
        }

        // Check for fork() availability (jailbreak indicator)
        let pid = fork()
        if pid >= 0 {
            if pid == 0 {
                exit(0)
            }
            detectedCount += 3
        }

        switch detectedCount {
        case 0: return .safe
        case 1...2: return .low
        case 3...4: return .medium
        case 5...7: return .high
        default: return .critical
        }
    }

    // MARK: - Network Security Analysis

    func analyzeNetworkConnections() -> ThreatLevel {
        var suspiciousConnections = 0
        let monitor = NWPathMonitor()

        monitor.pathUpdateHandler = { path in
            if path.status == .satisfied {
                // Check for suspicious network interfaces
                for interface in path.availableInterfaces {
                    if interface.type == .other {
                        suspiciousConnections += 1
                    }
                }
            }
        }

        let queue = DispatchQueue(label: "NetworkMonitor")
        monitor.start(queue: queue)

        // Simulate network analysis
        Thread.sleep(forTimeInterval: 0.5)
        monitor.cancel()

        return suspiciousConnections > 0 ? .medium : .safe
    }

    // MARK: - App Security Validation

    func validateAppIntegrity() -> ThreatLevel {
        guard let bundlePath = Bundle.main.bundlePath else {
            return .critical
        }

        var securityIssues = 0

        // Check for code signing
        let task = Process()
        task.launchPath = "/usr/bin/codesign"
        task.arguments = ["-v", bundlePath]

        let pipe = Pipe()
        task.standardOutput = pipe
        task.standardError = pipe

        do {
            try task.run()
            task.waitUntilExit()

            if task.terminationStatus != 0 {
                securityIssues += 2
            }
        } catch {
            securityIssues += 1
        }

        // Check for debugging tools
        let debuggingIndicators = [
            "DYLD_INSERT_LIBRARIES",
            "MSHookFunction",
            "substrate",
            "cycript"
        ]

        for indicator in debuggingIndicators {
            if getenv(indicator) != nil {
                securityIssues += 1
            }
        }

        switch securityIssues {
        case 0: return .safe
        case 1: return .low
        case 2: return .medium
        case 3...4: return .high
        default: return .critical
        }
    }

    // MARK: - Biometric Security

    func validateBiometricSecurity() -> ThreatLevel {
        let context = LAContext()
        var error: NSError?

        if context.canEvaluatePolicy(.deviceOwnerAuthenticationWithBiometrics, error: &error) {
            switch context.biometryType {
            case .faceID:
                return .safe
            case .touchID:
                return .safe
            case .none:
                return .medium
            @unknown default:
                return .low
            }
        } else {
            return .high
        }
    }

    // MARK: - Keychain Security

    func validateKeychainSecurity() -> ThreatLevel {
        let service = "jade.security.test"
        let account = "test_account"
        let data = "test_data".data(using: .utf8)!

        // Test keychain write
        let addQuery: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecValueData as String: data,
            kSecAttrAccessible as String: kSecAttrAccessibleWhenUnlockedThisDeviceOnly
        ]

        let addStatus = SecItemAdd(addQuery as CFDictionary, nil)

        // Test keychain read
        let readQuery: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecReturnData as String: kCFBooleanTrue!,
            kSecMatchLimit as String: kSecMatchLimitOne
        ]

        var result: AnyObject?
        let readStatus = SecItemCopyMatching(readQuery as CFDictionary, &result)

        // Cleanup
        let deleteQuery: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account
        ]
        SecItemDelete(deleteQuery as CFDictionary)

        if addStatus == errSecSuccess && readStatus == errSecSuccess {
            return .safe
        } else {
            return .high
        }
    }

    // MARK: - Device Profiling

    func generateDeviceSecurityProfile() -> DeviceSecurityProfile {
        let device = UIDevice.current

        return DeviceSecurityProfile(
            isJailbroken: detectJailbreak() != .safe,
            hasPasscode: LAContext().canEvaluatePolicy(.deviceOwnerAuthentication, error: nil),
            isBiometricEnabled: LAContext().canEvaluatePolicy(.deviceOwnerAuthenticationWithBiometrics, error: nil),
            osVersion: device.systemVersion,
            deviceModel: device.model,
            securityPatchLevel: "iOS-\(device.systemVersion)",
            encryptionStatus: true // iOS devices are encrypted by default
        )
    }

    // MARK: - Real-time Monitoring

    func startSecurityMonitoring() {
        guard !isMonitoring else { return }
        isMonitoring = true

        securityQueue.async { [weak self] in
            while self?.isMonitoring == true {
                self?.performSecurityScan()
                Thread.sleep(forTimeInterval: 5.0)
            }
        }
    }

    func stopSecurityMonitoring() {
        isMonitoring = false
    }

    private func performSecurityScan() {
        let jailbreakThreat = detectJailbreak()
        let networkThreat = analyzeNetworkConnections()
        let appThreat = validateAppIntegrity()
        let biometricThreat = validateBiometricSecurity()
        let keychainThreat = validateKeychainSecurity()

        let threats = [
            ("Jailbreak Detection", jailbreakThreat),
            ("Network Security", networkThreat),
            ("App Integrity", appThreat),
            ("Biometric Security", biometricThreat),
            ("Keychain Security", keychainThreat)
        ]

        for (eventType, threat) in threats {
            if threat != .safe {
                let event = SecurityEvent(
                    timestamp: Date(),
                    eventType: eventType,
                    threatLevel: threat,
                    description: "\(eventType) threat detected",
                    deviceInfo: [
                        "device": UIDevice.current.model,
                        "os": UIDevice.current.systemVersion,
                        "threat_level": threat.description
                    ]
                )

                securityEvents.append(event)

                if threat.rawValue >= ThreatLevel.high.rawValue {
                    NotificationCenter.default.post(
                        name: NSNotification.Name("JADESecurityAlert"),
                        object: event
                    )
                }
            }
        }
    }

    // MARK: - Security Report

    func generateSecurityReport() -> [String: Any] {
        let profile = generateDeviceSecurityProfile()
        let criticalEvents = securityEvents.filter { $0.threatLevel.rawValue >= ThreatLevel.high.rawValue }

        return [
            "timestamp": ISO8601DateFormatter().string(from: Date()),
            "device_profile": [
                "jailbroken": profile.isJailbroken,
                "passcode_enabled": profile.hasPasscode,
                "biometric_enabled": profile.isBiometricEnabled,
                "os_version": profile.osVersion,
                "device_model": profile.deviceModel,
                "encryption_status": profile.encryptionStatus
            ],
            "security_events": securityEvents.count,
            "critical_threats": criticalEvents.count,
            "monitoring_status": isMonitoring ? "ACTIVE" : "INACTIVE",
            "overall_threat_level": criticalEvents.isEmpty ? "SAFE" : "ELEVATED"
        ]
    }

    // MARK: - Demo Function

    @objc func runSecurityDemo() {
        print("🚀 JADE iOS Security Engine - Demo")
        print("📱 Comprehensive mobile security analysis")
        print("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")

        let jailbreakThreat = detectJailbreak()
        print("🔍 Jailbreak Detection: \(jailbreakThreat.emoji) \(jailbreakThreat.description)")

        let networkThreat = analyzeNetworkConnections()
        print("🌐 Network Security: \(networkThreat.emoji) \(networkThreat.description)")

        let appThreat = validateAppIntegrity()
        print("📋 App Integrity: \(appThreat.emoji) \(appThreat.description)")

        let biometricThreat = validateBiometricSecurity()
        print("👆 Biometric Security: \(biometricThreat.emoji) \(biometricThreat.description)")

        let keychainThreat = validateKeychainSecurity()
        print("🔐 Keychain Security: \(keychainThreat.emoji) \(keychainThreat.description)")

        let profile = generateDeviceSecurityProfile()
        print("\n📊 Device Security Profile:")
        print("   Model: \(profile.deviceModel)")
        print("   OS: \(profile.osVersion)")
        print("   Jailbroken: \(profile.isJailbroken ? "❌ YES" : "✅ NO")")
        print("   Passcode: \(profile.hasPasscode ? "✅ ENABLED" : "❌ DISABLED")")
        print("   Biometric: \(profile.isBiometricEnabled ? "✅ ENABLED" : "❌ DISABLED")")
        print("   Encryption: \(profile.encryptionStatus ? "✅ ENABLED" : "❌ DISABLED")")

        print("\n✅ JADE iOS Security analysis completed!")
    }
}

// MARK: - Objective-C Bridge for C++ Integration

@objc class JADEiOSBridge: NSObject {
    private let security = JADEiOSSecurity()

    @objc func initializeSecurity() {
        security.startSecurityMonitoring()
    }

    @objc func getSecurityReport() -> NSDictionary {
        return security.generateSecurityReport() as NSDictionary
    }

    @objc func runDemo() {
        security.runSecurityDemo()
    }
}

